def resolucao(p):
    if p.suffix == ".mp4":
        try:
            o = subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height", "-show_entries", "format=duration", "-of", "json", str(p)], capture_output=True, text=True).stdout
            j = json.loads(o); s = j["streams"][0]
            return f"{s['width']}x{s['height']} {float(j['format']['duration']):.1f}s"
        except Exception:
            return f"{p.stat().st_size // 1024} KB"
    try:
        from PIL import Image
        Image.MAX_IMAGE_PIXELS = None
        return "x".join(map(str, Image.open(p).size))
    except Exception:
        return f"{p.stat().st_size // 1024} KB"

def main():
    rows = []
    for arq, (tipo, url, acv, acs, lic, cred, ficha, obs) in T.items():
        p = V / "midia" / arq
        if not p.exists():
            continue
        rows.append(dict(arquivo=arq, tipo=tipo, blocos="", acervo=acs, id_acervo=acv, url=url, licenca=lic, credito=cred,
                         resolucao=resolucao(p), observacao=(obs + " " if obs else "") + f"Ficha sugerida: {ficha}"))
    with open(V / "midia.csv", "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
    L = ["# Licenças: 004-pearl-harbor", "", "Gerado por `tools/gera_midia_csv.py` (15/11/2026). Créditos vão **só na descrição** (bíblia, visual.md). Nada de CC BY-SA, CC BY, Getty/AP/IWM, colorização, TV. Regra do canal: nenhum corpo, ferido, sangue ou restos humanos.", "",
         "| arquivo | fonte | licença | crédito |", "|---|---|---|---|"]
    for r in rows:
        L.append(f"| `{r['arquivo']}` | {r['url']} | {r['licenca']} | {r['credito']} |")
    L += ["", "## Pontos de atenção",
          "- **Fotos japonesas de 1941** (`foto_ford_japonesa_80g30550`, `foto_ford_japonesa_80g30553_lado_norte`, `foto_hickam_kate_sobrevoa_1941`): fotos capturadas, custodiadas e publicadas pela Navy/NARA/NHHC e marcadas 'Public domain' no Commons. Aceitas com essa justificativa; se o Content ID disputar, trocar por NARA 80-G equivalente.",
          "- **Filmes 428-NPC (NARA, Naval Photographic Center):** cópias do archive.org (FedFlix). O NARA data o 428-NPC-1731 como 'Produced January 8, 1941' (erro: é pós-ataque). O 428-NPC-419 ('Pearl Harbor Attack', Movietone/Al Brick, dez/1942) foi descartado: é newsreel de terceiro (Movietone).",
          "- **Fotos DVIDS:** só as com etiqueta PUBLIC DOMAIN na página. As do Hangar 79 foram tiradas por militares da USAF (não são fotos do Pacific Aviation Museum).",
          "- **HABS/HAER (1991–93):** são da Library of Congress, não 'hoje' recente. Usar rótulo com o ano.",
          "- **Documentos recompostos (não capturas):** `doc_lei_116-9_sec2206_pearl_harbor`, `doc_dvids_pacaf_marcas_protegidas_lei`, `doc_dpaa_arizona_unknowns_texto` reproduzem o texto oficial em tipografia limpa (dpaa.mil/af.mil/DVIDS bloqueiam o Chromium da VPS). Citar a fonte original na descrição.",
          "- **Dano de 1941 hoje:** a NHL de Hickam (npgallery) e o DVIDS 238931 confirmam as marcas preservadas; a lei PL 116-9 é §2206 (não §2301) e não lista os sites do memorial."]
    (V / "licencas.md").write_text("\n".join(L) + "\n")
    print(len(rows), "linhas")
if __name__ == "__main__":
    main()
